            ci.cancel();
        }
    }
}

private boolean entityHit_SpellEngine_SaveDamageSource(Entity instance, DamageSource source, float amount, Operation<Boolean> original) {
    currentlyUsedDamageSource = source;
    return original.call(instance, source, amount);
}

private void damage_SpellEngine_Evasion(DamageSource source, float amount, CallbackInfoReturnable<Boolean> cir) {
    var entity = (LivingEntity) (Object) this;
    if (EvasionLogic.tryEvade(entity, amount, source)) {
        EvasionLogic.onEvade(entity, amount, source);
        lastEvaded = source;
        cir.setReturnValue(false);
        cir.cancel();
    }
}

public static boolean tryEvade(LivingEntity entity, float damage, DamageSource source) {
    if (entity.isSleeping()) {
        return false;
    }
    var config = SpellEngineMod.config;
    if (!config.attribute_evasion_allowed_while_spell_casting
            && entity instanceof SpellCaster.Player casterEntity
            && casterEntity.isCastingSpell()) {
        return false;
    }
    if (!config.attribute_evasion_allowed_while_item_usage && entity.isUsingItem()) {
        return false;
    }
    if (source.isIn(SpellEngineDamageTypeTags.EVADABLE)) {
        var chance = (float)SpellEngineAttributes.EVASION_CHANCE.asChance(entity.getAttributeValue(SpellEngineAttributes.EVASION_CHANCE.entry));

        var angleOfAttack = 0F;
        var evasionAngleLimit = config.attribute_evasion_angle;
        if (evasionAngleLimit > 0F && source.getSource() != null) {
            var sourcePos = source.getPosition() != null ? source.getPosition() : source.getSource().getPos();
            angleOfAttack = (float) VectorHelper.angleBetween(
                    entity.getRotationVec(1.0F),
                    new Vec3d(sourcePos.getX() - entity.getX(), 0, sourcePos.getZ() - entity.getZ())
            );
            angleOfAttack = Math.abs(angleOfAttack);
        }
        return chance > 0 && RNG.nextFloat() < chance && angleOfAttack <= evasionAngleLimit;
    }
    return false;
}

private static void parse(Registry<StatusEffect> registry) {
    registry.streamEntries().forEach(entry -> {
        var effect = entry.value();
        effect.forEachAttributeModifier(0, (attribute, modifier) -> {
            if (movementImpairingAttributes.contains(attribute)) {
                var isMovementImpairing = false;
                double treshold = 0;
                switch (modifier.operation()) {
                    case ADD_VALUE, ADD_MULTIPLIED_BASE -> {
                        treshold = 0;
                    }
                    case ADD_MULTIPLIED_TOTAL -> {
                        treshold = 1;
                    }
                }
                if (modifier.value() < treshold) {
                    isMovementImpairing = true;
                }
                if (isMovementImpairing) {
                    movementImpairingEffects.add(entry.getKey().get());
                }
            }
        });
    });
}

public static void init() {
    movementImpairingAttributes.add(EntityAttributes.GENERIC_MOVEMENT_SPEED);
    movementImpairingAttributes.add(EntityAttributes.GENERIC_FLYING_SPEED);
    movementImpairingAttributes.add(EntityAttributes.GENERIC_GRAVITY);
    PlatformEvents.onServerStarted((server) -> {
        parse(Registries.STATUS_EFFECT);
    });
}

public static boolean isMovementImpairing(RegistryEntry<StatusEffect> effect) {
    var key = effect.getKey();
    if (key.isEmpty()) { // Should never happen, added due to some incompatibility crash
        return false;
    }
    return movementImpairingEffects.contains(key.get());
}

public static boolean disablesMobAI(RegistryEntry<StatusEffect> effectEntry) {
    var effect = effectEntry.value();
    var actionsAllowed = ((ActionImpairing) effect).actionsAllowed();
    if (actionsAllowed == null) {
        return false;
    }
    return !actionsAllowed.mobs().canUseAI();
}

